mapper.select:
-- DATE_FORMAT(date_year,'%Y')
select `year` as time,sum(energy_value) as dd_value,
sum(dc_value) as dcValue,sum(zh_value) as zhValue
from year_energy
where deleted = 0

    and instrument_type = #{param.instrumentType}


    and date_year >= #{param.period.begin}


    and date_year <= #{param.period.end}

group by time order by time
